/**
 * 双人异地联机大富翁 —— 服务器（权威节点）
 * 功能：房间号联机 / 回合制核心 / 随机卡片 / 多地图主题 /
 *       多模式(经典·竞速·合作) / 小游戏格(石头剪刀布·答题) /
 *       断线重连 + 落盘存档
 * 运行：node server.js   (默认端口 3000，可用 PORT 环境变量覆盖)
 */
const path = require('path');
const fs = require('fs');
const http = require('http');
const express = require('express');
const { Server } = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = new Server(server);
const PAGE_HTML = Buffer.from('', 'base64');;;
// 禁用浏览器缓存：手机/微信内置浏览器常缓存旧版页面，导致按钮或重连遮罩行为陈旧
app.get('/', (req, res) => {
  res.set('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
  res.set('Pragma', 'no-cache');
  res.set('Expires', '0');
  res.type('text/html').send(PAGE_HTML);
});
// 内联 favicon，避免浏览器请求 /favicon.ico 产生 404
app.get('/favicon.ico', (req, res) => {
  res.type('image/svg+xml').send('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><text y=".9em" font-size="88">💕</text></svg>');
});

